import { reactAgent, AgentStep } from '@/lib/agent';

export const runtime = 'edge';

export async function POST(req: Request) {
  try {
    const { prompt, maxSteps } = await req.json();

    if (!prompt) {
      return new Response(JSON.stringify({ error: "Prompt is required." }), {
        status: 400,
        headers: { 'Content-Type': 'application/json' },
      });
    }

    const agentStream = reactAgent(prompt, maxSteps || 10);

    const readableStream = new ReadableStream({
      async start(controller) {
        try {
          for await (const step of agentStream) {
            const chunk = JSON.stringify(step) + '\n'; // NDJSON format
            controller.enqueue(new TextEncoder().encode(chunk));

            // Stop early if a final answer or unrecoverable error is reached
            if (step.type === 'final_answer' || step.type === 'error') {
              break;
            }
          }
        } catch (error: any) {
          console.error("Error during agent stream processing:", error);
          const errorChunk = JSON.stringify({
            type: 'error',
            content: { message: error.message, stack: error.stack }
          }) + '\n';
          controller.enqueue(new TextEncoder().encode(errorChunk));
        } finally {
          controller.close();
        }
      },
    });

    return new Response(readableStream, {
      headers: {
        'Content-Type': 'application/x-ndjson', // Newline-delimited JSON for streaming
        'Cache-Control': 'no-cache, no-transform',
        'Connection': 'keep-alive',
      },
    });

  } catch (error: any) {
    console.error("API route error:", error);
    // Catch errors before stream starts
    return new Response(JSON.stringify({
      error: "Failed to process request",
      details: error.message,
      stack: process.env.NODE_ENV === 'development' ? error.stack : undefined
    }), {
      status: 500,
      headers: { 'Content-Type': 'application/json' },
    });
  }
}

