export async function withExponentialBackoff<T>(
  fn: () => Promise<T>,
  retries: number = 3,
  initialDelay: number = 500, // milliseconds
  maxDelay: number = 10000,
  factor: number = 2
): Promise<T> {
  let delay = initialDelay;
  for (let i = 0; i <= retries; i++) {
    try {
      return await fn();
    } catch (error) {
      if (i === retries) {
        throw error; // Last retry failed, re-throw original error
      }
      console.warn(`Attempt ${i + 1} failed, retrying in ${delay}ms...`, error);
      await new Promise(resolve => setTimeout(resolve, delay));
      delay = Math.min(delay * factor, maxDelay); // Exponential increase, capped by maxDelay
    }
  }
  // This line should ideally not be reached if retries are handled correctly
  throw new Error("Function failed after multiple retries and backoff.");
}
