// ============================================================================
// lib/agent.ts
// ============================================================================
import { callLLM } from './llm';
import { executeTool } from './tools';

/**
 * Defines the structure for each step streamed by the AI agent.
 */
export type AgentStep = {
  type: 'thought' | 'action' | 'observation' | 'final_answer' | 'error';
  content: string | Record<string, any>;
  toolName?: string;
  toolArgs?: Record<string, any>;
};

/**
 * Implements an asynchronous ReAct (Reasoning and Acting) agent loop.
 * It iteratively generates thoughts, performs actions (tool calls), and processes observations.
 * @param initialPrompt The user's initial prompt to the agent.
 * @param maxSteps The maximum number of steps the agent can take before terminating.
 * @returns An async generator that yields AgentStep objects as the agent progresses.
 */
export async function* reactAgent(
  initialPrompt: string,
  maxSteps: number = 10
): AsyncGenerator<AgentStep> {
  let history: string[] = []; // Stores the dialogue and agent's internal monologue

  history.push(`Human: ${initialPrompt}`);

  for (let step = 0; step < maxSteps; step++) {
    try {
      // 1. Call LLM to generate Thought/Action or Final Answer
      const llmInput = history.join('\n\n'); // Join history to form the prompt for the LLM
      const llmResponse = await callLLM(llmInput);
      const llmContent = llmResponse.content.trim();

      const thoughtMatch = llmContent.match(/Thought:\s*(.*)/s);
      const actionMatch = llmContent.match(/Action:\s*(\{.*?\})/s); // Non-greedy match for JSON
      const finalAnswerMatch = llmContent.match(/Final Answer:\s*(.*)/s);

      if (finalAnswerMatch) {
        // If a final answer is found, the agent has completed its task.
        const answer = finalAnswerMatch[1].trim();
        yield { type: 'final_answer', content: answer };
        history.push(`AI: ${llmContent}`); // Add final output to history
        return; // Agent finished
      }

      if (thoughtMatch) {
        // Stream the agent's thought process.
        const thought = thoughtMatch[1].trim();
        yield { type: 'thought', content: thought };
        history.push(`AI: Thought: ${thought}`);
      }

      if (actionMatch) {
        // If an action is suggested, parse and execute it.
        const actionRaw = actionMatch[1];
        let actionData: { tool_name: string; args: Record<string, any> };
        try {
          actionData = JSON.parse(actionRaw);
        } catch (jsonError: any) {
          throw new Error(`Invalid JSON in Action: ${actionRaw}. Error: ${jsonError.message}`);
        }

        if (!actionData.tool_name || !actionData.args) {
          throw new Error(`Invalid action format: Missing tool_name or args in ${actionRaw}`);
        }

        yield { type: 'action', content: actionData, toolName: actionData.tool_name, toolArgs: actionData.args };
        history.push(`AI: Action: ${actionRaw}`);

        // 2. Execute the tool and get an observation.
        const observation = await executeTool(actionData.tool_name, actionData.args);
        yield { type: 'observation', content: observation };
        history.push(`Observation: ${JSON.stringify(observation)}`);

      } else if (!finalAnswerMatch) {
        // If LLM didn't provide a final answer and also no valid action, it's an unexpected state.
        throw new Error(`LLM output neither a Final Answer nor a valid Action: ${llmContent}. Current history fragment: ${llmInput.substring(0, 200)}...`);
      }

    } catch (error: any) {
      console.error("Agent loop error:", error);
      yield { type: 'error', content: { message: error.message, stack: error.stack } };
      return; // Terminate agent on error
    }
  }

  // If max steps reached without a final answer
  yield { type: 'error', content: `Agent reached maximum steps (${maxSteps}) without providing a final answer.` };
}
